xpath.script:
document.addEventListener('DOMContentLoaded', function () {
    var input = document.querySelector('input[name="x_studio_numero_de_autorizacion"]');
    var tablaProductos = document.querySelector('#ui_tabla_productos_visual tbody');

    function limpiarSoloNumeros(valor) {
        return (valor || '').replace(/\D/g, '');
    }

    function normalizarTexto(valor) {
        return (valor || '')
            .toString()
            .normalize('NFD')
            .replace(/[\u0300-\u036f]/g, '')
            .replace(/\s+/g, ' ')
            .trim()
            .toLowerCase();
    }

    function bloquearCampo(selector) {
        var field = document.querySelector(selector);
        if (!field) {
            return;
        }
        field.readOnly = true;
        field.setAttribute('readonly', 'readonly');
        field.classList.add('bg-light');
    }

    function setInputValue(selector, value) {
        var field = document.querySelector(selector);
        if (!field) {
            return;
        }
        field.value = value || '';
        field.readOnly = true;
        field.setAttribute('readonly', 'readonly');
        field.classList.add('bg-light');
        field.dispatchEvent(new Event('input', { bubbles: true }));
        field.dispatchEvent(new Event('change', { bubbles: true }));
    }

    function detectarSiFilaEsMoto(fila) {
        if (!fila) {
            return false;
        }

        var valorActual = fila.getAttribute('data-es-moto');
        if (valorActual === '1') {
            return true;
        }
        if (valorActual === '0') {
            return false;
        }

        var primerTd = fila.querySelector('td');
        var textoFila = normalizarTexto(primerTd ? primerTd.textContent : fila.textContent);

        if (!textoFila) {
            fila.setAttribute('data-es-moto', '0');
            return false;
        }

        var productos = window.mis_productos_odoo || [];
        var esMoto = productos.some(function (prod) {
            if (!prod || !prod.es_moto) {
                return false;
            }

            var nombre = normalizarTexto(prod.name || '');
            var barcode = normalizarTexto(prod.barcode || '');
            var atributos = normalizarTexto(prod.mis_atributos || '');
            var compuesto = normalizarTexto((prod.name || '') + ' ' + (prod.mis_atributos || ''));

            if (nombre && textoFila.indexOf(nombre) !== -1) return true;
            if (barcode && textoFila.indexOf(barcode) !== -1) return true;
            if (atributos && textoFila.indexOf(atributos) !== -1) return true;
            if (compuesto && textoFila.indexOf(compuesto) !== -1) return true;
            return false;
        });

        fila.setAttribute('data-es-moto', esMoto ? '1' : '0');
        return esMoto;
    }

    function actualizarVisibilidadDocumentosMoto() {
        var bloque = document.getElementById('bloque_documentos_moto');
        var inputFile = document.getElementById('attachment');

        if (!bloque) return;

        var hayMoto = false;
        var filas = document.querySelectorAll('#ui_tabla_productos_visual tbody tr');

        filas.forEach(function (fila) {
            if (detectarSiFilaEsMoto(fila)) {
                hayMoto = true;
            }
        });

        if (hayMoto) {
            bloque.style.display = '';
            if (inputFile) inputFile.required = true;
        } else {
            bloque.style.display = 'none';
            if (inputFile) {
                inputFile.required = false;
                inputFile.value = '';
            }
        }
    }

    if (!input) return;
    if (document.getElementById('btn_consultar_autorizacion')) return;

    var form = input.closest('form');
    var submitBtn = null;
    if (form) {
        submitBtn =
            form.querySelector('.s_website_form_send') ||
            form.querySelector('button[type="submit"]') ||
            form.querySelector('.oe_submit_btn');
    }

    function ocultarBotonCrear() {
        if (submitBtn) {
            submitBtn.style.display = 'none';
            submitBtn.disabled = true;
        }
    }

    function mostrarBotonCrear() {
        if (submitBtn) {
            submitBtn.style.display = '';
            submitBtn.disabled = false;
        }
    }

    function contarArticulos() {
        return document.querySelectorAll('#ui_tabla_productos_visual tbody tr').length;
    }

    function tieneArticulos() {
        return contarArticulos() > 0;
    }

    function tieneDatosCompletos(data) {
        if (!data) return false;

        return !!(
            (data.nombre || '').trim() &&
            (data.telefono || '').trim() &&
            (data.nit || '').trim() &&
            (data.dpi || '').trim() &&
            (data.direccion || '').trim()
        );
    }

    function direccionEntregaValida() {
        var campo = document.querySelector(
            'input[name="x_studio_direccion_entrega"], textarea[name="x_studio_direccion_entrega"]'
        );
        if (!campo) return false;
        return (campo.value || '').trim().length > 0;
    }

    function puedeCrearTicket() {
        var flag = document.getElementById('autorizacion_validada_ok');
        var valorConsultado = document.getElementById('autorizacion_consultada_valor');
        var autorizacionActual = limpiarSoloNumeros(input.value).trim();

        var autorizacionValida = flag && flag.value === '1';
        var mismaAutorizacion = valorConsultado && valorConsultado.value === autorizacionActual;
        var articulosValidos = tieneArticulos();
        var direccionValida = direccionEntregaValida();

        return !!(autorizacionValida && mismaAutorizacion && articulosValidos && direccionValida);
    }

    function reevaluarBotonCrear() {
        if (puedeCrearTicket()) {
            mostrarBotonCrear();
        } else {
            ocultarBotonCrear();
        }
    }

    function setEstadoAutorizacion(valido, autorizacion) {
        var flag = document.getElementById('autorizacion_validada_ok');
        var valor = document.getElementById('autorizacion_consultada_valor');

        if (flag) {
            flag.value = valido ? '1' : '0';
        }
        if (valor) {
            valor.value = autorizacion || '';
        }

        reevaluarBotonCrear();
    }

    if (tablaProductos) {
        var observer = new MutationObserver(function () {
            actualizarVisibilidadDocumentosMoto();
            reevaluarBotonCrear();
        });

        observer.observe(tablaProductos, {
            childList: true,
            subtree: true,
            characterData: true
        });

        tablaProductos.addEventListener('input', function () {
            actualizarVisibilidadDocumentosMoto();
            reevaluarBotonCrear();
        });

        tablaProductos.addEventListener('change', function () {
            actualizarVisibilidadDocumentosMoto();
            reevaluarBotonCrear();
        });

        tablaProductos.addEventListener('click', function () {
            setTimeout(function () {
                actualizarVisibilidadDocumentosMoto();
                reevaluarBotonCrear();
            }, 50);
        });
    }

    actualizarVisibilidadDocumentosMoto();
    reevaluarBotonCrear();

    bloquearCampo('input[name="x_studio_nombre_del_cliente"]');
    bloquearCampo('input[name="x_studio_telefono_cliente"]');
    bloquearCampo('input[name="x_studio_nit_del_cliente"]');
    bloquearCampo('input[name="x_studio_dpi_del_cliente"]');
    bloquearCampo('input[name="x_studio_direccion_del_cliente"]');
    bloquearCampo('input[name="x_studio_valor_factura"]');
    bloquearCampo('input[name="x_studio_valor_pagare"]');
    bloquearCampo('input[name="x_studio_poe"]');

    var campoDireccionEntrega = document.querySelector(
        'input[name="x_studio_direccion_entrega"], textarea[name="x_studio_direccion_entrega"]'
    );
    if (campoDireccionEntrega) {
        campoDireccionEntrega.required = true;
        campoDireccionEntrega.addEventListener('input', function () {
            reevaluarBotonCrear();
        });
        campoDireccionEntrega.addEventListener('change', function () {
            reevaluarBotonCrear();
        });
    }

    var contenedorInput = input.parentElement;
    if (!contenedorInput) return;

    var wrapper = document.createElement('div');
    wrapper.className = 'd-flex align-items-center gap-2';

    contenedorInput.insertBefore(wrapper, input);
    wrapper.appendChild(input);

    input.style.flex = '1';
    input.style.minWidth = '0';
    input.setAttribute('inputmode', 'numeric');
    input.setAttribute('autocomplete', 'off');
    input.setAttribute('maxlength', '20');

    var btn = document.createElement('button');
    btn.type = 'button';
    btn.id = 'btn_consultar_autorizacion';
    btn.className = 'btn btn-primary';
    btn.textContent = 'Consultar';
    btn.style.whiteSpace = 'nowrap';
    btn.disabled = true;
    wrapper.appendChild(btn);

    var msg = document.createElement('div');
    msg.id = 'msg_consulta_autorizacion';
    msg.className = 'small mt-2 d-none';
    contenedorInput.appendChild(msg);

    function actualizarEstadoBoton() {
        var valor = limpiarSoloNumeros(input.value);
        btn.disabled = !valor;
    }

    function limpiarCamposConsulta() {
        setInputValue('input[name="x_studio_nombre_del_cliente"]', '');
        setInputValue('input[name="x_studio_telefono_cliente"]', '');
        setInputValue('input[name="x_studio_nit_del_cliente"]', '');
        setInputValue('input[name="x_studio_dpi_del_cliente"]', '');
        setInputValue('input[name="x_studio_direccion_del_cliente"]', '');
        setInputValue('input[name="x_studio_valor_factura"]', '');
        setInputValue('input[name="x_studio_valor_pagare"]', '');
        setInputValue('input[name="x_studio_poe"]', '');
    }

    ocultarBotonCrear();
    setEstadoAutorizacion(false, '');

    input.addEventListener('input', function () {
        var limpio = limpiarSoloNumeros(input.value);
        if (input.value !== limpio) {
            input.value = limpio;
        }

        setEstadoAutorizacion(false, '');
        limpiarCamposConsulta();

        msg.classList.add('d-none');
        msg.classList.remove('text-danger', 'text-success');
        btn.textContent = 'Consultar';
        actualizarEstadoBoton();
    });

    input.addEventListener('keypress', function (e) {
        var charCode = e.which || e.keyCode;
        if (charCode === 8 || charCode === 13) return;
        var charStr = String.fromCharCode(charCode);
        if (!/[0-9]/.test(charStr)) {
            e.preventDefault();
        }
    });

    input.addEventListener('paste', function () {
        setTimeout(function () {
            input.value = limpiarSoloNumeros(input.value);
            setEstadoAutorizacion(false, '');
            limpiarCamposConsulta();
            actualizarEstadoBoton();
        }, 0);
    });

    actualizarEstadoBoton();

    btn.addEventListener('click', async function () {
        var autorizacion = limpiarSoloNumeros(input.value).trim();
        input.value = autorizacion;

        msg.classList.add('d-none');
        msg.classList.remove('text-danger', 'text-success');

        if (!autorizacion) {
            msg.textContent = 'Debe ingresar el número de autorización.';
            msg.classList.remove('d-none');
            msg.classList.add('text-danger');
            btn.disabled = true;
            setEstadoAutorizacion(false, '');
            return;
        }

        btn.disabled = true;
        btn.textContent = 'Consultando...';

        try {
            const response = await fetch('/consultar/autorizacion', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ autorizacion: autorizacion })
            });

            const rpc = await response.json();
            const data = rpc.result || {};

            if (data.ok && tieneDatosCompletos(data.data)) {
                msg.textContent = data.message || 'Consulta realizada correctamente.';
                msg.classList.remove('d-none');
                msg.classList.add('text-success');

                setInputValue('input[name="x_studio_nombre_del_cliente"]', data.data.nombre);
                setInputValue('input[name="x_studio_telefono_cliente"]', data.data.telefono);
                setInputValue('input[name="x_studio_nit_del_cliente"]', data.data.nit);
                setInputValue('input[name="x_studio_dpi_del_cliente"]', data.data.dpi);
                setInputValue('input[name="x_studio_direccion_del_cliente"]', data.data.direccion);
                setInputValue('input[name="x_studio_valor_factura"]', data.data.factura);
                setInputValue('input[name="x_studio_valor_pagare"]', data.data.pagare);
                setInputValue('input[name="x_studio_poe"]', data.data.poe);

                setEstadoAutorizacion(true, autorizacion);

                btn.textContent = 'Consultado';
                btn.disabled = false;
            } else {
                limpiarCamposConsulta();
                setEstadoAutorizacion(false, '');

                msg.textContent = data.message || 'La consulta no fue exitosa o no devolvió todos los datos requeridos.';
                msg.classList.remove('d-none');
                msg.classList.add('text-danger');
                btn.textContent = 'Consultar';
                btn.disabled = false;
            }
        } catch (error) {
            limpiarCamposConsulta();
            setEstadoAutorizacion(false, '');
            msg.textContent = 'Ocurrió un error al consultar la autorización.';
            msg.classList.remove('d-none');
            msg.classList.add('text-danger');
            btn.textContent = 'Consultar';
            btn.disabled = false;
        }
    });

    if (form) {
        form.addEventListener('submit', function (e) {
            var flag = document.getElementById('autorizacion_validada_ok');
            var valorConsultado = document.getElementById('autorizacion_consultada_valor');
            var autorizacionActual = limpiarSoloNumeros(input.value).trim();

            var autorizacionValida = flag && flag.value === '1';
            var mismaAutorizacion = valorConsultado && valorConsultado.value === autorizacionActual;

            if (!autorizacionActual) {
                e.preventDefault();
                msg.textContent = 'Debe ingresar y consultar el número de autorización antes de crear el ticket.';
                msg.classList.remove('d-none', 'text-success');
                msg.classList.add('text-danger');
                ocultarBotonCrear();
                return false;
            }

            if (!autorizacionValida || !mismaAutorizacion) {
                e.preventDefault();
                msg.textContent = 'Debe validar correctamente la autorización y obtener datos antes de crear el ticket.';
                msg.classList.remove('d-none', 'text-success');
                msg.classList.add('text-danger');
                ocultarBotonCrear();
                return false;
            }

            if (!tieneArticulos()) {
                e.preventDefault();
                msg.textContent = 'Debe agregar al menos un artículo antes de crear el ticket.';
                msg.classList.remove('d-none', 'text-success');
                msg.classList.add('text-danger');
                ocultarBotonCrear();
                return false;
            }

            if (!direccionEntregaValida()) {
                e.preventDefault();
                msg.textContent = 'Debe ingresar la dirección de entrega de producto.';
                msg.classList.remove('d-none', 'text-success');
                msg.classList.add('text-danger');
                ocultarBotonCrear();
                return false;
            }
        });
    }
});
